UPDATE public.paid_aragon_awards a SET enrichment =
jsonb_set(jsonb_set(a.enrichment, '{project_operations}',
  (SELECT coalesce(jsonb_agg(CASE WHEN m.mapping ? (op->>'operation_code') AND op->>'source_file'='feder-aragon-2021-2027-20261001.json'
    THEN op || jsonb_build_object('indicators',m.mapping->(op->>'operation_code')) ELSE op END),'[]'::jsonb)
   FROM jsonb_array_elements(a.enrichment->'project_operations') op)), '{related_company_operations}',
  (SELECT coalesce(jsonb_agg(CASE WHEN m.mapping ? (op->>'operation_code') AND op->>'source_file'='feder-aragon-2021-2027-20261001.json'
    THEN op || jsonb_build_object('indicators',m.mapping->(op->>'operation_code')) ELSE op END),'[]'::jsonb)
   FROM jsonb_array_elements(a.enrichment->'related_company_operations') op))
FROM indicator_map m WHERE a.enrichment->>'version'='1';
